window.kbPageData["views/entry/k-895da8f86516614f"] = {"key":"entry/k-895da8f86516614f","state":{"route":"entry/k-895da8f86516614f"},"node":{"id":"k-895da8f86516614f","mode":"k","title":"反间谍传唤的家属通知","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["反间谍传唤应及时向家属告知原因，无法通知或可能妨碍调查的情形消失后应立即通知"],"qs":["国考 2024 副省级 行测#11"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"国家安全机关应当及时将传唤原因通知被传唤人家属。无法通知或者通知可能妨碍调查时，可暂缓通知，相关情形消失后应当立即通知。","review":{"definition":"国家安全机关应当及时将传唤原因通知被传唤人家属。无法通知或者通知可能妨碍调查时，可暂缓通知，相关情形消失后应当立即通知。","explanation":"甲仍有间谍行为嫌疑，并不当然妨碍家属通知。A项以嫌疑是否消除决定能否通知，改变了法定的暂缓通知条件，因此是本题的错误选项。","references":[],"evidence":"除无法通知或者可能妨碍调查的情形以外","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 副省级 行测#11":{"paper":"国考 2024 副省级 行测","n":11,"mod":"常识判断","src":["a566fec37e508ca7f975.pdf",3],"asrc":["a475ecf57d968bc14cd6.pdf",4],"card":"3d1cdb46e11b81e8ae124960","links":[{"id":"k-895da8f86516614f","role":"直接考查","why":"通知时点取决于能否通知及通知是否可能妨碍调查。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-895da8f86516614f":[["国考 2024 副省级 行测#11"]]}};
